# Fixes jumbled/overlapping vendor portal header on mobile by adding
# a hamburger menu, reusing the exact same CSS classes already used
# by the main site nav (.nav-hamburger, .nav-overlay, .nav-mobile-hide).

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\VendorHeader.tsx"), $bytes)
Write-Host "NEW: src\components\VendorHeader.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\vendor\(protected)\layout.tsx"), $bytes)
Write-Host "UPDATED: src\app\vendor\(protected)\layout.tsx" -ForegroundColor Green

Write-Host "`nBoth files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan